python3 -c "
import pathlib
p = pathlib.Path('tools/gen_builtins.rs')
t = p.read_text()
old = '''/// Returns the documentation spelling for a neutral PHP type.
fn type_name(ty: TypeSpec) -> &'static str {
    match ty {'''
new = '''/// Returns the documentation spelling for a neutral PHP type.
fn type_name(ty: TypeSpec) -> String {
    match ty {'''
assert t.count(old) == 1
t = t.replace(old, new, 1)
old = '''        TypeSpec::Ptr => \"pointer\",
        TypeSpec::Callable => \"callable\",
    }
}'''
new = '''        TypeSpec::Ptr => \"pointer\",
        TypeSpec::Callable => \"callable\",
        // php spells an explicit null in a union, and the distinction is load-bearing: a scalar
        // parameter declared \`?int \$x = null\` accepts an omitted argument AND a written null,
        // where a plain \`int\` accepts only the first.
        TypeSpec::Nullable(inner) => return format!(\"?{}\", type_name(*inner)),
    }
    .to_string()
}'''
assert t.count(old) == 1
t = t.replace(old, new, 1)
p.write_text(t)
print('gen_builtins.rs: Nullable renders as php spells it')
"; cargo build --example gen_builtins 2>&1 | grep -E "^error" -A 10 | head -20: gen_builtins.rs: Nullable renders as php spells it
